// <<< sounds
const bytes = (uri) => { const s = atob(uri.slice(uri.indexOf(',') + 1)), b = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) b[i] = s.charCodeAt(i); return b.buffer; };
